//! Prebaked PS1 CUE database (PSXtract-2 `cue/` at commit
//! 4691fc405698d53927df6e4f59c3e9b113c13706) embedded as `cue_db.bin`, generated by
//! `tools/psx_cue_db.py` (see its docstring for the grammar the generator accepts).
//!
//! Blob format (little endian, unaligned):
//!   header 16 bytes: "PSCD", version u32 = 1, count u32, total u32 (whole blob)
//!   offsets: count x u32, absolute record offsets, keys strictly ascending (bytewise)
//!   record: key_len u8, key, title_len u16, title (UTF-8, ".bin" removed), md5 [16],
//!           leadout u32 (frames), track_count u8 (1..99),
//!           tracks x { number u8, flags u8 (bit0 audio, bit1 has INDEX 00),
//!                      index01 u32, index00 u32 (0 when absent) }
//!   trailer: crc32 u32 (IEEE) of everything before it
//! All times are frames (MM*4500 + SS*75 + FF).
//!
//! Lookup follows PSXtract (`select_cue_variant_and_update_serial`): `_` -> `-`, an
//! exact key wins; otherwise the variants `<key>-1` .. `<key>-10` that exist.
//! (Deviation from the plan table: `lookup` fills a caller buffer instead of returning
//! a static slice, and `Candidate` exposes tracks through `track(i)` because the
//! embedded blob is unaligned and cannot be viewed as a `[]CueTrack`.  The MD5 and
//! lead-out are non-optional: the generator rejects files without them.)
//!
//! The "overrides" half reproduces `parse_prebaked_cue_pregaps` (per audio track with
//! number > 1: pregap and length in frames) and the way the PSXtract revision 3 helper
//! (with our patch) consumes it in `build_audio_at3` and `convert_wav_to_bin`.
const std = @import("std");

const blob: []const u8 = @embedFile("cue_db.bin");

pub const magic = "PSCD";
pub const version: u32 = 1;
pub const header_len = 16;
pub const track_record_len = 10;
pub const max_tracks = 99;
/// Exact key plus `-1` .. `-10`.
pub const max_candidates = 11;
pub const sector_size: i64 = 2352;
/// PSXtract GAP_FRAMES: 2 seconds.
pub const gap_frames: i64 = 150;
const int_max: i64 = std.math.maxInt(i32);

pub const Error = error{
    /// Embedded blob is damaged (generator/embedding bug).
    CorruptCueDb,
    /// An audio track has no pregap override entry.
    MissingPregapOverride,
    /// A computed frame/byte count is negative or does not fit PSXtract's `int`s.
    InvalidTrackLayout,
};

pub const CueTrack = struct {
    number: u8,
    is_audio: bool,
    /// INDEX 01, frames.
    start_frames: u32,
    /// INDEX 00, frames, when the CUE has one.
    index00_frames: ?u32,

    /// INDEX 01 - INDEX 00 in frames; null when the track has no INDEX 00.
    pub fn pregapFrames(self: CueTrack) ?i32 {
        const idx0 = self.index00_frames orelse return null;
        return @intCast(@as(i64, self.start_frames) - @as(i64, idx0));
    }
};

pub const Candidate = struct {
    key: []const u8,
    title: []const u8,
    data_md5: [16]u8,
    leadout_frames: u32,
    track_count: u8,
    track_bytes: []const u8,

    pub fn track(self: Candidate, i: usize) CueTrack {
        std.debug.assert(i < self.track_count);
        const b = self.track_bytes[i * track_record_len ..][0..track_record_len];
        const flags = b[1];
        return .{
            .number = b[0],
            .is_audio = flags & 1 != 0,
            .start_frames = std.mem.readInt(u32, b[2..6], .little),
            .index00_frames = if (flags & 2 != 0) std.mem.readInt(u32, b[6..10], .little) else null,
        };
    }
};

fn rd16(off: usize) u16 {
    return std.mem.readInt(u16, blob[off..][0..2], .little);
}

fn rd32(off: usize) u32 {
    return std.mem.readInt(u32, blob[off..][0..4], .little);
}

fn recordCount() usize {
    return rd32(8);
}

fn recordOffset(i: usize) usize {
    return rd32(header_len + 4 * i);
}

/// Decode record `i`; assumes the blob passed `validate`.
fn recordAt(i: usize) Candidate {
    var pos = recordOffset(i);
    const klen: usize = blob[pos];
    const key = blob[pos + 1 ..][0..klen];
    pos += 1 + klen;
    const tlen: usize = rd16(pos);
    const title = blob[pos + 2 ..][0..tlen];
    pos += 2 + tlen;
    const md5 = blob[pos..][0..16].*;
    const leadout = rd32(pos + 16);
    const ntracks = blob[pos + 20];
    pos += 21;
    return .{
        .key = key,
        .title = title,
        .data_md5 = md5,
        .leadout_frames = leadout,
        .track_count = ntracks,
        .track_bytes = blob[pos..][0 .. @as(usize, ntracks) * track_record_len],
    };
}

fn validateBlob() Error!void {
    if (blob.len < header_len + 4 or !std.mem.eql(u8, blob[0..4], magic)) return error.CorruptCueDb;
    if (rd32(4) != version or rd32(12) != blob.len) return error.CorruptCueDb;
    const n_records: usize = recordCount();
    if (n_records == 0 or n_records > (blob.len - header_len - 4) / 4) return error.CorruptCueDb;
    const end = blob.len - 4;
    if (rd32(end) != std.hash.Crc32.hash(blob[0..end])) return error.CorruptCueDb;
    var pos: usize = header_len + 4 * n_records;
    var previous: ?[]const u8 = null;
    for (0..n_records) |i| {
        if (recordOffset(i) != pos) return error.CorruptCueDb;
        // Fixed part of a record: key_len(1) key title_len(2) title md5(16) leadout(4) tracks(1).
        if (pos + 1 > end) return error.CorruptCueDb;
        const klen: usize = blob[pos];
        if (klen == 0 or pos + 1 + klen + 2 > end) return error.CorruptCueDb;
        const key = blob[pos + 1 ..][0..klen];
        if (previous) |p| {
            if (std.mem.order(u8, p, key) != .lt) return error.CorruptCueDb;
        }
        previous = key;
        for (key) |c| if (c == '_' or c < 0x21 or c > 0x7e) return error.CorruptCueDb;
        pos += 1 + klen;
        const tlen: usize = rd16(pos);
        if (pos + 2 + tlen + 21 > end) return error.CorruptCueDb;
        if (tlen == 0 or !std.unicode.utf8ValidateSlice(blob[pos + 2 ..][0..tlen])) return error.CorruptCueDb;
        pos += 2 + tlen + 16;
        const ntracks: usize = blob[pos + 4];
        if (ntracks == 0 or ntracks > max_tracks) return error.CorruptCueDb;
        pos += 5;
        if (pos + ntracks * track_record_len > end) return error.CorruptCueDb;
        var last: i64 = -1;
        for (0..ntracks) |t| {
            const b = blob[pos + t * track_record_len ..][0..track_record_len];
            const idx1: i64 = std.mem.readInt(u32, b[2..6], .little);
            const idx0: i64 = std.mem.readInt(u32, b[6..10], .little);
            if (b[0] != t + 1 or b[1] > 3) return error.CorruptCueDb;
            if (b[1] & 2 == 0 and idx0 != 0) return error.CorruptCueDb;
            if (b[1] & 2 != 0 and idx0 > idx1) return error.CorruptCueDb;
            if (t == 0 and b[1] & 1 != 0) return error.CorruptCueDb;
            if (idx1 <= last) return error.CorruptCueDb;
            last = idx1;
        }
        if (rd32(pos - 5) <= last) return error.CorruptCueDb;
        pos += ntracks * track_record_len;
    }
    if (pos != end) return error.CorruptCueDb;
}

/// 0 = unchecked, 1 = valid, 2 = corrupt.  Validation is pure and idempotent, so a
/// racing first call at worst validates twice.
var validation_state: std.atomic.Value(u8) = .init(0);

/// Validate the embedded blob (once per process).
pub fn validate() Error!void {
    switch (validation_state.load(.acquire)) {
        1 => return,
        2 => return error.CorruptCueDb,
        else => {},
    }
    validateBlob() catch {
        validation_state.store(2, .release);
        return error.CorruptCueDb;
    };
    validation_state.store(1, .release);
}

/// Number of records in the database.
pub fn count() usize {
    validate() catch @panic("corrupt cue_db.bin");
    return recordCount();
}

fn find(key: []const u8) ?Candidate {
    var lo: usize = 0;
    var hi: usize = recordCount();
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const rec = recordAt(mid);
        switch (std.mem.order(u8, rec.key, key)) {
            .eq => return rec,
            .lt => lo = mid + 1,
            .gt => hi = mid,
        }
    }
    return null;
}

/// Find the prebaked CUE candidates for a disc serial (`SCUS_94167`, `SCUS-94167`).
/// An exact key match wins and is the only candidate; otherwise every existing
/// `<serial>-1` .. `<serial>-10`, in ascending order.  Returns a prefix of `out`
/// (empty when nothing matches, including serials longer than any key).
pub fn lookup(serial: []const u8, out: *[max_candidates]Candidate) []const Candidate {
    validate() catch @panic("corrupt cue_db.bin");
    var buf: [64]u8 = undefined;
    // Room for the "-10" suffix.
    if (serial.len == 0 or serial.len > buf.len - 3) return out[0..0];
    for (serial, 0..) |c, i| buf[i] = if (c == '_') '-' else c;
    if (find(buf[0..serial.len])) |rec| {
        out[0] = rec;
        return out[0..1];
    }
    var n: usize = 0;
    var variant: u8 = 1;
    while (variant <= 10) : (variant += 1) {
        const suffix = std.fmt.bufPrint(buf[serial.len..], "-{d}", .{variant}) catch unreachable;
        if (find(buf[0 .. serial.len + suffix.len])) |rec| {
            out[n] = rec;
            n += 1;
        }
    }
    return out[0..n];
}

/// Whether `md5` equals the candidate's `REM MD5` (data track MD5).
pub fn md5Matches(c: Candidate, md5: *const [16]u8) bool {
    return std.mem.eql(u8, &c.data_md5, md5);
}

// ---- PSXtract pregap / length derivation --------------------------------------------

pub const Override = struct {
    /// Pregap of the track, frames (PSXtract `timestamps[i]`).
    pregap_frames: i32,
    /// Track length, frames (PSXtract `track_lengths[i]`); 0 when PSXtract leaves it unset.
    length_frames: i32,
};

/// PSXtract `PREGAP_OVERRIDE`: one entry per audio track with number > 1, in CUE order
/// (index 0 = first such track = PSX track 2 unless the CUE has a second data track).
pub const Overrides = struct {
    len: u8 = 0,
    items: [max_tracks]Override = @splat(.{ .pregap_frames = 0, .length_frames = 0 }),
};

/// Port of `parse_prebaked_cue_pregaps`.  Null when the CUE has no audio track beyond
/// track 1 (PSXtract returns NULL and uses its defaults).
pub fn overrides(c: Candidate) ?Overrides {
    var result: Overrides = .{};
    const n: i64 = c.track_count;
    for (0..c.track_count) |ti| {
        const t = c.track(ti);
        const tn: i64 = t.number;
        if (tn <= 1 or !t.is_audio) continue;
        var pregap: i64 = undefined;
        var current: i64 = undefined;
        if (t.index00_frames) |idx0| {
            pregap = @as(i64, t.start_frames) - idx0;
            current = idx0;
        } else {
            pregap = gap_frames;
            current = @as(i64, t.start_frames) - gap_frames;
        }
        var length: i64 = 0;
        if (tn < n) {
            const next = c.track(@intCast(tn));
            const next_start: i64 = next.index00_frames orelse next.start_frames;
            length = next_start - current;
        } else if (c.leadout_frames > 0) {
            length = @as(i64, c.leadout_frames) - current;
        }
        result.items[result.len] = .{
            .pregap_frames = @intCast(pregap),
            .length_frames = @intCast(length),
        };
        result.len += 1;
    }
    if (result.len == 0) return null;
    return result;
}

/// `get_track_size_from_cue`: frames of a CDDA track from raw TOC INDEX 01 positions
/// (absolute MM*4500+SS*75+FF as PSXtract decodes them, i.e. including the 2 s
/// lead-in).  `next_abs` is the following track's position, or null for the last
/// track, in which case the lead-out position is used with no gap subtracted.
pub fn tocTrackFrames(cur_abs: i64, next_abs: ?i64, leadout_abs: i64) i64 {
    const cur = cur_abs - gap_frames;
    const next = if (next_abs) |v| v - gap_frames else leadout_abs;
    return next - cur;
}

fn frameLimit() i64 {
    return @divTrunc(int_max, sector_size);
}

fn checkedFrames(v: i64) Error!i64 {
    if (v < 0 or v > frameLimit()) return error.InvalidTrackLayout;
    return v;
}

/// `build_audio_at3` (revision 3 patch): sectors PSXtract records for audio track
/// `track_num` (2-based PSX track number, i.e. CDDA entry `track_num - 2`) in the AT3
/// header (`fact_param1 = sectors * 2352 / 4`), from the TOC track size
/// (`tocTrackFrames`) and the optional CUE override.  A present override without an
/// entry for the track is an error, as in the patched helper.
pub fn at3TrackSectors(toc_frames: i64, ov: ?*const Overrides, track_num: u32) Error!u32 {
    var size = toc_frames;
    if (ov) |o| {
        if (track_num < 2 or track_num - 2 >= o.len) return error.MissingPregapOverride;
        const curr = try checkedFrames(o.items[track_num - 2].pregap_frames);
        if (track_num - 1 < o.len) {
            const next = try checkedFrames(o.items[track_num - 1].pregap_frames);
            if (next < gap_frames and curr >= gap_frames) size += gap_frames - next;
        } else if (curr < gap_frames) {
            size -= gap_frames - curr;
        }
    }
    return @intCast(try checkedFrames(size));
}

/// Byte layout of one reconstructed audio track BIN (`convert_wav_to_bin`, patched).
pub const BinLayout = struct {
    /// Zero bytes before the PCM (PSXtract's sparse `(gap - 1) * 2352`).
    pregap_bytes: u32,
    /// PCM bytes wanted after the pregap (zero-padded when the WAV is shorter).
    data_bytes: u32,
    /// Final file size: pregap + data, extended to the AT3 header's size if larger.
    total_bytes: u32,
};

/// `convert_wav_to_bin` size arithmetic for PSX track `track_num` (>= 2).  `data_gap` is
/// the data-track gap used for track 2 (`cdrom.dataGap`), `expected_bytes` is
/// `at3TrackSectors * 2352` (the AT3 `fact_param1 * 4`).
pub fn binLayout(ov: ?*const Overrides, track_num: u32, data_gap: i64, expected_bytes: i64) Error!BinLayout {
    if (track_num < 2 or expected_bytes < 0 or expected_bytes > int_max) return error.InvalidTrackLayout;
    const idx = track_num - 2;
    var gap = gap_frames;
    if (ov) |o| {
        if (idx < o.len) gap = o.items[idx].pregap_frames;
    }
    const pregap = ((if (track_num == 2) data_gap else gap) - 1) * sector_size;
    if (pregap <= 0 or pregap > int_max) return error.InvalidTrackLayout;
    var target = expected_bytes;
    if (ov) |o| {
        if (idx < o.len) {
            const cue_size = (try checkedFrames(o.items[idx].length_frames)) * sector_size;
            if (cue_size > pregap) target = cue_size;
        }
    }
    if (target < pregap) return error.InvalidTrackLayout;
    return .{
        .pregap_bytes = @intCast(pregap),
        .data_bytes = @intCast(target - pregap),
        .total_bytes = @intCast(@max(target, expected_bytes)),
    };
}

// ---- tests ------------------------------------------------------------------------

test "embedded blob validates" {
    try validate();
    try std.testing.expect(count() > 10000);
}

test "exact key wins" {
    var buf: [max_candidates]Candidate = undefined;
    const r = lookup("ESPM-70001", &buf);
    try std.testing.expectEqual(@as(usize, 1), r.len);
    try std.testing.expectEqualStrings("ESPM-70001", r[0].key);
    try std.testing.expectEqualStrings("Iceman - Digital PlayStage (Japan)", r[0].title);
    var want: [16]u8 = undefined;
    _ = try std.fmt.hexToBytes(&want, "a9602fe84d2d9a707b283ab2afd5da8b");
    try std.testing.expect(md5Matches(r[0], &want));
    try std.testing.expectEqual(@as(u32, 57 * 4500 + 55 * 75 + 56), r[0].leadout_frames);
    try std.testing.expectEqual(@as(u8, 1), r[0].track_count);
    const t = r[0].track(0);
    try std.testing.expect(!t.is_audio);
    try std.testing.expectEqual(@as(u32, 0), t.start_frames);
    try std.testing.expectEqual(@as(?u32, null), t.index00_frames);
    try std.testing.expectEqual(@as(?Overrides, null), overrides(r[0]));
}

test "underscore serial maps to dash" {
    var buf: [max_candidates]Candidate = undefined;
    const r = lookup("ESPM_70001", &buf);
    try std.testing.expectEqual(@as(usize, 1), r.len);
    try std.testing.expectEqualStrings("ESPM-70001", r[0].key);
}

test "-N variants in ascending order" {
    var buf: [max_candidates]Candidate = undefined;
    const r = lookup("SCUS_94167", &buf);
    try std.testing.expectEqual(@as(usize, 2), r.len);
    try std.testing.expectEqualStrings("SCUS-94167-1", r[0].key);
    try std.testing.expectEqualStrings("Jet Moto 2 (USA)", r[0].title);
    try std.testing.expectEqualStrings("SCUS-94167-2", r[1].key);
    try std.testing.expectEqualStrings("Jet Moto 2 - Championship Edition (USA)", r[1].title);
    try std.testing.expect(!std.mem.eql(u8, &r[0].data_md5, &r[1].data_md5));
    try std.testing.expectEqual(@as(u8, 17), r[0].track_count);
    const t2 = r[0].track(1);
    try std.testing.expect(t2.is_audio);
    try std.testing.expectEqual(@as(u8, 2), t2.number);
    try std.testing.expectEqual(@as(u32, 13 * 4500 + 13 * 75 + 14), t2.start_frames);
    try std.testing.expectEqual(@as(?u32, 13 * 4500 + 11 * 75 + 14), t2.index00_frames);
    try std.testing.expectEqual(@as(?i32, 150), t2.pregapFrames());
    // A variant key is also reachable exactly.
    const exact = lookup("SCUS-94167-2", &buf);
    try std.testing.expectEqual(@as(usize, 1), exact.len);
    try std.testing.expectEqualStrings("SCUS-94167-2", exact[0].key);
}

test "missing serials" {
    var buf: [max_candidates]Candidate = undefined;
    try std.testing.expectEqual(@as(usize, 0), lookup("SCUS-00000", &buf).len);
    try std.testing.expectEqual(@as(usize, 0), lookup("", &buf).len);
    try std.testing.expectEqual(@as(usize, 0), lookup("SCUS-94167-3", &buf).len);
    try std.testing.expectEqual(@as(usize, 0), lookup("scus-94167", &buf).len);
    try std.testing.expectEqual(@as(usize, 0), lookup(&@as([80]u8, @splat('X')), &buf).len);
}

test "every key is found by exact lookup" {
    try validate();
    var buf: [max_candidates]Candidate = undefined;
    for (0..recordCount()) |i| {
        const rec = recordAt(i);
        const r = lookup(rec.key, &buf);
        try std.testing.expectEqual(@as(usize, 1), r.len);
        try std.testing.expectEqualStrings(rec.key, r[0].key);
    }
}

test "overrides: Jet Moto 2 (all INDEX 00 present)" {
    var buf: [max_candidates]Candidate = undefined;
    const c = lookup("SCUS-94167", &buf)[0];
    const o = overrides(c).?;
    try std.testing.expectEqual(@as(u8, 16), o.len);
    try std.testing.expectEqual(Override{ .pregap_frames = 150, .length_frames = 13755 }, o.items[0]);
    try std.testing.expectEqual(Override{ .pregap_frames = 150, .length_frames = 13510 }, o.items[1]);
    try std.testing.expectEqual(Override{ .pregap_frames = 150, .length_frames = 11444 }, o.items[2]);
    // Last track: lead-out based.
    try std.testing.expectEqual(Override{ .pregap_frames = 150, .length_frames = 13610 }, o.items[15]);
    try std.testing.expectEqual(Override{ .pregap_frames = 0, .length_frames = 0 }, o.items[16]);
}

test "overrides: missing INDEX 00 uses the default 2 s pregap" {
    var buf: [max_candidates]Candidate = undefined;
    const c = lookup("SCES-00063", &buf)[0];
    try std.testing.expect(c.track(2).index00_frames == null);
    const o = overrides(c).?;
    try std.testing.expectEqual(Override{ .pregap_frames = 300, .length_frames = 25450 }, o.items[0]);
    try std.testing.expectEqual(Override{ .pregap_frames = 150, .length_frames = 20593 }, o.items[1]);
    try std.testing.expectEqual(Override{ .pregap_frames = 150, .length_frames = 28218 }, o.items[2]);
}

test "overrides: second data track is not an audio ordinal" {
    var buf: [max_candidates]Candidate = undefined;
    const c = lookup("SCED-02672", &buf)[0];
    try std.testing.expectEqual(@as(u8, 2), c.track_count);
    try std.testing.expect(!c.track(1).is_audio);
    try std.testing.expectEqual(@as(?Overrides, null), overrides(c));
}

test "overrides for every record match the C-parser port in tools/psx_cue_db.py" {
    try validate();
    // CRC-32 over, per record in key order: len u8, then (pregap i32, length i32) LE pairs.
    // The reference value comes from the generator's line-by-line port of
    // parse_prebaked_cue_pregaps run on the raw CUE text.
    var crc = std.hash.Crc32.init();
    for (0..recordCount()) |i| {
        const c = recordAt(i);
        const o = overrides(c) orelse Overrides{};
        crc.update(&.{o.len});
        for (o.items[0..o.len]) |item| {
            var b: [8]u8 = undefined;
            std.mem.writeInt(i32, b[0..4], item.pregap_frames, .little);
            std.mem.writeInt(i32, b[4..8], item.length_frames, .little);
            crc.update(&b);
        }
    }
    try std.testing.expectEqual(@as(u32, 0xeb6dfde5), crc.final());
}

test "tocTrackFrames" {
    // Middle track: next start minus current start (both lose the 2 s lead-in).
    try std.testing.expectEqual(@as(i64, 1000), tocTrackFrames(5000, 6000, 99999));
    // Last track runs to the lead-out with no gap subtracted from it.
    try std.testing.expectEqual(@as(i64, 1000 + 150), tocTrackFrames(5000, null, 6000));
}

test "at3TrackSectors follows build_audio_at3" {
    var o: Overrides = .{ .len = 3 };
    o.items[0] = .{ .pregap_frames = 150, .length_frames = 1 };
    o.items[1] = .{ .pregap_frames = 75, .length_frames = 1 };
    o.items[2] = .{ .pregap_frames = 100, .length_frames = 1 };
    // No override: TOC size as is.
    try std.testing.expectEqual(@as(u32, 1000), try at3TrackSectors(1000, null, 2));
    // Next pregap short while this one is full: padded by the shortfall.
    try std.testing.expectEqual(@as(u32, 1075), try at3TrackSectors(1000, &o, 2));
    // This pregap already short: unchanged.
    try std.testing.expectEqual(@as(u32, 1000), try at3TrackSectors(1000, &o, 3));
    // Last track with a short pregap is truncated.
    try std.testing.expectEqual(@as(u32, 1000), try at3TrackSectors(1050, &o, 4));
    try std.testing.expectError(error.MissingPregapOverride, at3TrackSectors(1000, &o, 5));
    try std.testing.expectError(error.InvalidTrackLayout, at3TrackSectors(-1, null, 2));
    try std.testing.expectError(error.InvalidTrackLayout, at3TrackSectors(10, &o, 4));
}

test "binLayout follows convert_wav_to_bin" {
    var o: Overrides = .{ .len = 2 };
    o.items[0] = .{ .pregap_frames = 150, .length_frames = 200 };
    o.items[1] = .{ .pregap_frames = 300, .length_frames = 10 };
    // No override: 150-frame gap, expected size from the AT3 header.
    var l = try binLayout(null, 3, 0, 1000 * sector_size);
    try std.testing.expectEqual(@as(u32, 149 * 2352), l.pregap_bytes);
    try std.testing.expectEqual(@as(u32, (1000 - 149) * 2352), l.data_bytes);
    try std.testing.expectEqual(@as(u32, 1000 * 2352), l.total_bytes);
    // Track 2 uses the data gap; the CUE length wins when larger than the pregap.
    l = try binLayout(&o, 2, 200, 100 * sector_size);
    try std.testing.expectEqual(@as(u32, 199 * 2352), l.pregap_bytes);
    try std.testing.expectEqual(@as(u32, 1 * 2352), l.data_bytes);
    try std.testing.expectEqual(@as(u32, 200 * 2352), l.total_bytes);
    // CUE length smaller than the pregap is ignored (expected size used); total >= expected.
    l = try binLayout(&o, 3, 0, 400 * sector_size);
    try std.testing.expectEqual(@as(u32, 299 * 2352), l.pregap_bytes);
    try std.testing.expectEqual(@as(u32, 101 * 2352), l.data_bytes);
    try std.testing.expectEqual(@as(u32, 400 * 2352), l.total_bytes);
    // Expected size shorter than the pregap is an error.
    try std.testing.expectError(error.InvalidTrackLayout, binLayout(null, 3, 0, 100 * sector_size));
    // Gap of one frame or less gives no pregap.
    try std.testing.expectError(error.InvalidTrackLayout, binLayout(null, 2, 1, 100 * sector_size));
}
